import sim,mujoco
s=sim.Sim()
print('nbody',s.model.nbody)
for i in range(s.model.nbody):
    name=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_BODY,i)
    if name:
        print(i,name)
print('\\nnbodies with link in name or hand or finger:')
for i in range(s.model.nbody):
    name=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_BODY,i)
    if name and ('link' in name or 'hand' in name or 'finger' in name):
        print(i,name)
print('\\nsite list around hand:')
for i in range(s.model.nsite):
    n=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_SITE,i)
    if n:
        if 'hand' in n.lower() or 'finger' in n.lower() or 'panda' in n.lower():
            print(i,n)
